export interface MdsInputMaskConfig {
  /**
   * For mask: 'regex'. The regex to apply to the field, ignoring / or flags.
   * E.g. to allow only characters in the input, use "^[a-zA-Z]+$".
   */
  regex?: string;
  /**
   * For mask: 'integer'. Turns off thousands commas for the integer mask.
   * Default: true.
   */
  commas?: boolean;
  /**
   * For mask: 'integer'. Allow leading zeroes and remove commas.
   * Overrides any other mask configuration (i.e. commas).
   * Default: false.
   */
  leadingZeroes?: boolean;
  /**
   * For mask: 'zip'. The formatting of the zip mask based on the country code.
   * Default: 'US'.
   */
  countryCode?: 'US' | 'CA';
  /**
   * For mask type 'custom' or to override an existing mask config but keep the decorator.
   * E.g. `percent` or `currency` to provide your own configuration but keep the $ or %.
   * Pass in an iMask config object. See https://imask.js.org/guide.html.
   *
   * E.g.
   *
   * {
   *  mask: 'num',
   *  blocks: {
   *    num: {
   *      mask: Number,
   *      min: 0,
   *      max: 100,
   *      radix: '.',
   *    },
   *  },
   */
  iMaskConfig?: object;
}
